\version "2.27.2"
% automatically converted by musicxml2ly from 34a-Print-Object-Spanners.xml
\pointAndClickOff

%% additional definitions required by the score:
hideNote =
  \tweak Dots.transparent ##t
  \tweak NoteHead.transparent ##t
  \tweak NoteHead.no-ledgers ##t
  \tweak Stem.transparent ##t
  \tweak Accidental.transparent ##t
  \tweak Rest.transparent ##t
  \tweak TabNoteHead.transparent ##t \etc


\header {
  texidoc = "Test various spanner elements (mostly from <notations>) starting
    from a <note> object with ‘print-object’ set to ‘no’, then test spanners
    ending with such a note object: beam, tuplet, slur, trill + wavy-line,
    glissando (wavy), slide (solid), two-note tremolo, hammer-on, pull-off.
    Spanners starting from an invisible object should be suppressed."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative b' {
  \clef "treble" \numericTimeSignature \time 4/4 \key c \major \hideNote b8 [ b8
  b8 b8 ] b8 [ b8 b8 \hideNote b8 ] | % 1
  \tweak TupletBracket.direction #UP \tweak TupletBracket.transparent ##t \tweak
  TupletNumber.transparent ##t \tuplet 3/2 {
    \hideNote b4 b4 b4 }
  \tweak TupletBracket.direction #DOWN \tuplet 3/2 {
    b4 b4 \hideNote b4 }
  | % 2
  \hideNote a4 \tweak transparent ##t ^( c4 ) a4 _( \hideNote c4 ) | % 3
  \hideNote b4 \tweak transparent ##t \startTrillSpan b4 \stopTrillSpan b4
  \startTrillSpan \hideNote b4 \stopTrillSpan | % 4
  \once \override Glissando.style = #'trill \hideNote e4 \tweak transparent ##t
  \glissando c,4 \once \override Glissando.style = #'trill e'4 \glissando
  \hideNote c,4 | % 5
  \hideNote e'4 \tweak transparent ##t \glissando c,4 e'4 \glissando \hideNote
  c,4 | % 6
  \once \override Beam.gap-count = 2 \repeat tremolo 8 { \hideNote a'32 c32 }
  \once \override Beam.gap-count = 2 \repeat tremolo 8 { a32 \hideNote c32 } | % 7
  \hideNote b4 b4 b4 \hideNote b4 | % 8
  \hideNote b4 b4 b4 \hideNote b4 }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
